const crypto = require('crypto');

const secret = ($env && $env.N8N_WEBHOOK_SECRET) ? String($env.N8N_WEBHOOK_SECRET) : '';
const discordUrl = ($env && $env.DISCORD_WEBHOOK_URL) ? String($env.DISCORD_WEBHOOK_URL).trim() : '';
const item = $input.first();
const headers = item.json.headers || {};
const receivedSig = String(headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '').trim();

// Extract exact raw body for byte-accurate HMAC verification
let rawBody = '';
if (item.binary && item.binary.data && item.binary.data.data) {
  rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else if (typeof item.json.body === 'string') {
  rawBody = item.json.body;
} else {
  rawBody = JSON.stringify(item.json.body ?? {});
}

let valid = false;
try {
  if (secret && receivedSig && rawBody) {
    const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
    const bufA = Buffer.from(receivedSig, 'utf8');
    const bufB = Buffer.from(expectedSig, 'utf8');
    if (bufA.length === bufB.length) {
      valid = crypto.timingSafeEqual(bufA, bufB);
    }
  }
} catch (_) {
  valid = false;
}

if (!valid) {
  return [{ json: { valid: false, error: 'Invalid HMAC-SHA256 signature' } }];
}

// Data minimization: extract only the minimal fields required for notification & callback
const parsed = typeof item.json.body === 'object' && item.json.body !== null
  ? item.json.body
  : JSON.parse(rawBody);

const loanId = String(parsed.loanId || '');
const event = String(parsed.event || 'updated');
const toolName = String(parsed.toolName || 'Tool');
const borrowerName = String(parsed.borrowerName || 'Neighbor');
const ownerName = String(parsed.ownerName || 'Owner');
const startDate = String(parsed.startDate || '');
const endDate = String(parsed.endDate || '');
const idempotencyKey = String(parsed.idempotencyKey || `${loanId}:${event}:${Date.now()}`);

const eventSummaryMap = {
  created: `New borrow request for "${toolName}" by ${borrowerName} (${startDate} to ${endDate})`,
  approved: `${ownerName} approved ${borrowerName}'s request for "${toolName}"`,
  declined: `${ownerName} declined ${borrowerName}'s request for "${toolName}"`,
  returned: `${ownerName} marked "${toolName}" as returned by ${borrowerName}`
};

const cardMessageMap = {
  created: 'Request notification sent',
  approved: 'Approval notification sent',
  declined: 'Decline notification sent',
  returned: 'Return confirmation sent'
};

const notificationText = eventSummaryMap[event] || `Loan update (${event}) for "${toolName}"`;
const callbackPayloadObj = {
  loanId,
  idempotencyKey,
  eventType: `loan_${event}`,
  message: cardMessageMap[event] || 'Notification sent'
};
const callbackBody = JSON.stringify(callbackPayloadObj);
const callbackSignature = 'sha256=' + crypto.createHmac('sha256', secret).update(callbackBody, 'utf8').digest('hex');

return [{
  json: {
    valid: true,
    loanId,
    event,
    notificationText,
    hasDiscordWebhook: Boolean(discordUrl),
    discordPayload: JSON.stringify({ content: `**[LendLoop]** ${notificationText}` }),
    callbackBody,
    callbackSignature
  }
}];

const item = $input.first().json;
console.log(`[LendLoop Notification] ${item.notificationText}`);
return [{ json: item }];
